import os
import torch

# ==========================================
# General Configuration
# ==========================================
SEED = 42
DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
NUM_WORKERS = 4  # Optimized for 12 vCPUs

# ==========================================
# File Paths
# ==========================================
INPUT_DIR = "./input"
TRAIN_DICOM_DIR = os.path.join(INPUT_DIR, "train")
TEST_DICOM_DIR = os.path.join(INPUT_DIR, "test")

# Metadata generated by the previous step
METADATA_DIR = "./metadata"
TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
TEST_CSV = os.path.join(METADATA_DIR, "test.csv")
SAMPLE_SUBMISSION_CSV = os.path.join(INPUT_DIR, "sample_submission.csv")

# Working Directory for Idea 7 (SAP-Net)
WORKING_DIR = "./working/idea_7"
CACHE_DIR = os.path.join(WORKING_DIR, "cache")
CHECKPOINT_DIR = os.path.join(WORKING_DIR, "checkpoints")
BEST_MODEL_PATH = os.path.join(CHECKPOINT_DIR, "best_model.pth")

# Submission Output
SUBMISSION_DIR = "./submission"
