# ==========================================
# Data Configuration
# ==========================================
IMG_SIZE = 224  # Input resolution for the CNN backbone
N_SLICES = 3  # Number of slices: Apical, Middle, Basal
SLICE_AREA_THRESHOLD = 50  # Threshold to identify lung tissue in HU

# ==========================================
# Model Configuration
# ==========================================
BACKBONE = "efficientnet_b0"
PRETRAINED = True
UNFREEZE_BACKBONE = True  # Unfreeze top blocks for domain adaptation
EMBEDDING_DIM = 128  # Dimension of the projected image features

# ==========================================
# Training Configuration
# ==========================================
EPOCHS = 50
BATCH_SIZE = 32

# Differential Learning Rates (Backbone vs Head)
LR_BACKBONE = 1e-4
LR_HEAD = 1e-3
WEIGHT_DECAY = 1e-2

# Learning Rate Scheduler (Cosine Annealing)
T_MAX = 50
ETA_MIN = 1e-6

# ==========================================
# Metric & Loss Configuration
# ==========================================
# Constants for the Laplace Log Likelihood Metric
METRIC_CLIP_SIGMA = 70.0
METRIC_MAX_DELTA = 1000.0

# Training Stability
# Small floor for sigma during training to prevent NLL singularity (log(0))
# This is distinct from the metric clip; this is for gradient flow.
TRAIN_SIGMA_FLOOR = 0.05
